/**
 * frontend/src/components/App.jsx - APPLICATION PRINCIPALE
 * ✅ Layout + Navigation + Auth
 */

import React, { useState, useEffect, useRef } from 'react';
import Login from '../pages/Login';
import Dashboard from './Dashboard';
import Enrollment from './Enrollment';
import CameraRecognition from './CameraRecognition';
import authService from '../auth_service';
import { studentsAPI } from '../api_service';

const COLORS = {
  primary: '#4F46E5',
  background: '#F8FAFC',
  surface: '#FFFFFF',
  textMain: '#1E293B',
  textMuted: '#64748B',
  border: '#E2E8F0',
  sidebar: '#1E293B'
};

const App = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [currentUser, setCurrentUser] = useState(null);
  const [currentView, setCurrentView] = useState('dashboard');
  const [notifications, setNotifications] = useState([]);
  const [loading, setLoading] = useState(true);

  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState([]);
  const [showResults, setShowResults] = useState(false);

  const debounceRef = useRef(null);

  useEffect(() => {
    authService.initialize();

    if (authService.isAuthenticated()) {
      setCurrentUser(authService.getUser());
      setIsAuthenticated(true);
    }

    setLoading(false);
  }, []);

  const addNotification = (message, type = 'info') => {
    const id = Date.now();
    setNotifications((prev) => [...prev, { id, message, type }]);

    setTimeout(() => {
      setNotifications((prev) => prev.filter((n) => n.id !== id));
    }, 4000);
  };

  const handleSearch = (value) => {
    setSearchQuery(value);

    if (debounceRef.current) {
      clearTimeout(debounceRef.current);
    }

    if (value.trim().length < 2) {
      setSearchResults([]);
      setShowResults(false);
      return;
    }

    debounceRef.current = setTimeout(async () => {
      try {
        const result = await studentsAPI.search(value);

        if (result.success) {
          setSearchResults(result.data.results || []);
          setShowResults((result.data.results || []).length > 0);
        } else {
          setSearchResults([]);
          setShowResults(false);
        }
      } catch (error) {
        console.error('❌ Search error:', error);
        setSearchResults([]);
        setShowResults(false);
        addNotification('❌ Erreur de recherche', 'error');
      }
    }, 400);
  };

  const handleSelectStudent = (student) => {
    if (!student || typeof student !== 'object') return;

    const studentName = String(student.name || 'Inconnu').trim();
    setSearchQuery(studentName);
    setShowResults(false);
    addNotification(`👤 Étudiant sélectionné: ${studentName}`, 'info');
  };

  const handleLoginSuccess = (user) => {
    setCurrentUser(user);
    setIsAuthenticated(true);
    addNotification(
      `✅ Bienvenue ${user.first_name || user.username}`,
      'success'
    );
  };

  const handleLogout = async () => {
    await authService.logout();
    setCurrentUser(null);
    setIsAuthenticated(false);
    setSearchQuery('');
    setSearchResults([]);
    addNotification('👋 Déconnexion réussie', 'info');
  };

  if (loading) {
    return <div style={styles.loading}>⏳ Chargement...</div>;
  }

  if (!isAuthenticated) {
    return <Login onLoginSuccess={handleLoginSuccess} />;
  }

  return (
    <div style={styles.appWrapper}>
      <aside style={styles.sidebar}>
        <div style={styles.brand}>
          <div style={styles.brandIcon}>Σ</div>
          <h2 style={styles.brandName}>Attendance OS</h2>
        </div>

        <nav style={styles.sideNav}>
          <NavItem
            active={currentView === 'dashboard'}
            onClick={() => setCurrentView('dashboard')}
            icon="📊"
            label="Dashboard"
          />
          <NavItem
            active={currentView === 'enrollment'}
            onClick={() => setCurrentView('enrollment')}
            icon="➕"
            label="Enrôlement"
          />
          <NavItem
            active={currentView === 'camera'}
            onClick={() => setCurrentView('camera')}
            icon="📷"
            label="Reconnaissance"
          />
        </nav>

        <div style={styles.userInfo}>
          <div style={styles.userAvatar}>👤</div>
          <div>
            <div style={styles.userName}>
              {currentUser?.first_name || currentUser?.username}
            </div>
            <div style={styles.userRole}>Administrateur</div>
          </div>
        </div>

        <button onClick={handleLogout} style={styles.logoutBtn}>
          🚪 Déconnexion
        </button>
      </aside>

      <main style={styles.main}>
        <header style={styles.topBar}>
          <div style={{ position: 'relative', width: 420 }}>
            <div style={styles.searchBar}>
              🔍
              <input
                style={styles.searchInput}
                value={searchQuery}
                onChange={(e) => handleSearch(e.target.value)}
                onFocus={() =>
                  searchResults.length > 0 && setShowResults(true)
                }
                placeholder="Rechercher un étudiant..."
              />
            </div>

            {showResults && searchResults.length > 0 && (
              <div style={styles.dropdown}>
                {searchResults.map((student, index) => (
                  <div
                    key={`student-${index}`}
                    style={styles.resultItem}
                    onClick={() => handleSelectStudent(student)}
                  >
                    <div style={{ fontWeight: 600 }}>
                      {student.name || 'Inconnu'}
                    </div>
                    <div style={{ fontSize: 12, color: '#64748B' }}>
                      ID: {student.student_id || student.id || '-'}
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </header>

        <div style={styles.content}>
          {currentView === 'dashboard' && (
            <Dashboard addNotification={addNotification} />
          )}
          {currentView === 'enrollment' && (
            <Enrollment addNotification={addNotification} />
          )}
          {currentView === 'camera' && (
            <CameraRecognition addNotification={addNotification} />
          )}
        </div>
      </main>

      <div style={styles.toastContainer}>
        {notifications.map((n) => (
          <div key={n.id} style={styles.toast}>
            {n.message}
          </div>
        ))}
      </div>
    </div>
  );
};

const NavItem = ({ active, icon, label, onClick }) => (
  <div
    onClick={onClick}
    style={{
      padding: 12,
      cursor: 'pointer',
      color: active ? '#4F46E5' : '#94A3B8',
      fontWeight: 500,
      transition: 'color 0.2s'
    }}
  >
    {icon} {label}
  </div>
);

const styles = {
  loading: {
    height: '100vh',
    display: 'grid',
    placeItems: 'center',
    fontSize: '1.2rem',
    color: COLORS.textMuted
  },
  appWrapper: {
    display: 'flex',
    height: '100vh',
    overflow: 'hidden'
  },
  sidebar: {
    width: 260,
    background: COLORS.sidebar,
    color: 'white',
    padding: 20,
    overflowY: 'auto',
    display: 'flex',
    flexDirection: 'column'
  },
  brand: {
    display: 'flex',
    gap: 10,
    marginBottom: 30
  },
  brandIcon: {
    width: 40,
    height: 40,
    background: COLORS.primary,
    display: 'grid',
    placeItems: 'center',
    borderRadius: 8,
    fontSize: 20,
    fontWeight: 'bold',
    color: 'white'
  },
  brandName: {
    margin: 0,
    fontSize: 18,
    fontWeight: 'bold',
    color: 'white',
    lineHeight: '40px'
  },
  sideNav: {
    marginBottom: 20,
    flex: 1
  },
  userInfo: {
    display: 'flex',
    gap: 12,
    padding: 12,
    background: 'rgba(255,255,255,0.1)',
    borderRadius: 8,
    marginBottom: 20
  },
  userAvatar: {
    width: 40,
    height: 40,
    display: 'grid',
    placeItems: 'center',
    fontSize: '1.5rem'
  },
  userName: {
    fontWeight: 600,
    fontSize: '0.9rem'
  },
  userRole: {
    fontSize: '0.8rem',
    opacity: 0.7
  },
  searchBar: {
    display: 'flex',
    gap: 10,
    padding: 10,
    background: '#F1F5F9',
    borderRadius: 8,
    alignItems: 'center'
  },
  searchInput: {
